130: {
131:     const char *delim = fn ? strstr(fn, HTS_IDX_DELIM) : NULL, *ext;
132:     if (!fn) return -1;
133:     if (!delim) delim = fn + strlen(fn);
134:     for (ext = delim; ext > fn && *ext != '.' && *ext != '/'; --ext) {}
135:     if (*ext == '.' &&
136:         ((delim - ext == 3 && ext[1] == 'g' && ext[2] == 'z') || // permit .sam.gz as a valid file extension
